import React from 'react';
import { FiShoppingBag, FiStar, FiGift, FiUsers, FiLayout, FiMessageSquare, FiBarChart2, FiHome } from 'react-icons/fi';

const Sidebar = () => {
  return (
    <div className="sidebar">
      <h2 className="logo">BRESS</h2>
      <ul className="nav-list">
        <li><FiHome /> Dashboard</li>
        <li><FiShoppingBag /> Orders</li>
        <li><FiStar /> Reviews</li>
        <li><FiGift /> Vouchers</li>
        <li><FiUsers /> B2B Inquiries</li>
        <li><FiLayout /> Collections</li>
        <li><FiBarChart2 /> Products</li>
        <li><FiMessageSquare /> Live Chat</li>
      </ul>
    </div>
  );
};

export default Sidebar;
